using System.Globalization;
using DimensionalQuantities.Numerics;
using DimensionalQuantities.Roslyn.Discovery;

namespace DimensionalQuantities.Roslyn.Generators;

internal static class PowerSourceEmitter
{
	public static string Emit(QuantityGenerationPlan plan)
	{
		string classes = string.Join("\n\n", plan.PowerOperations.GroupBy(operation => operation.ExponentTypeName)
			.Select((group, index) => RenderClass(group.Key, group, index, plan)));
		return $$"""
			// <auto-generated />
			namespace DimensionalQuantities.Generated;

			{{classes}}
			""";
	}

	private static string RenderClass(string exponentTypeName, IEnumerable<PowerOperation> operations, int index, QuantityGenerationPlan plan)
	{
		string methods = string.Join("\n\t\t", operations.Select(operation => RenderMethod(operation, plan)));
		return $$"""
			internal static class PowerExtensions{{index}}
			{
				extension(global::DimensionalQuantities.TypeSystem.Power<{{exponentTypeName}}>)
				{
					{{methods}}
				}
			}
			""";
	}

	private static string RenderMethod(PowerOperation operation, QuantityGenerationPlan plan)
	{
		string operand = plan.GetQuantityName(operation.Operand);
		string magnitude = RenderMagnitude(operation.Exponent);
		if (operation.Result == default)
		{
			return $"public static double Of({operand} value) => {magnitude};";
		}

		string result = plan.GetQuantityName(operation.Result);
		return $"public static {result} Of({operand} value) => {result}.FromSiBaseUnit({magnitude});";
	}

	private static string RenderMagnitude(Rational exponent)
	{
		string value = "value.AsSiBaseUnit()";
		string power = ((double)exponent).ToString("R", CultureInfo.InvariantCulture) + "d";
		if (!exponent.Denominator.IsOne && !exponent.Denominator.IsEven)
		{
			string absolutePower = $"global::System.Math.Pow(global::System.Math.Abs({value}), {power})";
			return exponent.Numerator.IsEven ? absolutePower : $"({value} < 0 ? -{absolutePower} : {absolutePower})";
		}

		return $"global::System.Math.Pow({value}, {power})";
	}
}
